import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void pointwise_conv_kernel(
    const float* input, 
    const float* weight, 
    const float* bias, 
    float* output,
    int N, 
    int C_in, 
    int H, 
    int W, 
    int C_out, 
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int totalElements = N * C_out * H * W;
    if (idx < totalElements) {
        int wIndex = idx % W;
        int hIndex = (idx / W) % H;
        int cOutIndex = (idx / (H * W)) % C_out;
        int nIndex = idx / (C_out * H * W);

        float sum = 0.0f;
        int weightOffset = cOutIndex * C_in;
        int inputOffset = nIndex * C_in * H * W + hIndex * W + wIndex;
        for (int cInIndex = 0; cInIndex < C_in; cInIndex++) {
            sum += input[inputOffset + cInIndex * H * W] * weight[weightOffset + cInIndex];
        }
        if (has_bias) {
            sum += bias[cOutIndex];
        }
        output[idx] = sum;
    }
}

torch::Tensor pointwise_conv_forward(
    torch::Tensor input, 
    torch::Tensor weight, 
    torch::Tensor bias
) {
    auto N = input.size(0);
    auto C_in = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);
    auto C_out = weight.size(0);

    bool has_bias = (bias.numel() > 0);
    auto output = torch::zeros({N, C_out, H, W}, torch::dtype(input.dtype()).device(input.device()));

    int totalElements = N * C_out * H * W;
    const int block_size = 256;
    const int grid_size = (totalElements + block_size - 1) / block_size;

    pointwise_conv_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, C_in, H, W, C_out, has_bias
    );

    return output;
}
""".strip()

conv_stub = "torch::Tensor pointwise_conv_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

pointwise_conv = load_inline(
    name="custom_pointwise_conv",
    cpp_sources=conv_stub,
    cuda_sources=conv_source,
    extra_cflags=["-O3"],
    extra_ldflags=[],
    functions=["pointwise_conv_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Performs a pointwise 2D convolution operation with a custom CUDA kernel.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.use_bias = bias

        # Initialize weights in [out_channels, in_channels] shape
        w = torch.empty((out_channels, in_channels), dtype=torch.float32)
        nn.init.kaiming_uniform_(w, a=math.sqrt(5))
        self.weight = nn.Parameter(w)

        # Initialize bias if requested
        if bias:
            fan_in = in_channels
            bound = 1 / math.sqrt(fan_in)
            b = torch.empty((out_channels,), dtype=torch.float32)
            nn.init.uniform_(b, -bound, bound)
            self.bias = nn.Parameter(b)
        else:
            self.bias = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Forward pass using custom CUDA kernel
        if self.bias is not None:
            return pointwise_conv.pointwise_conv_forward(
                x, 
                self.weight, 
                self.bias
            )
        else:
            # Pass an empty tensor to indicate no bias
            return pointwise_conv.pointwise_conv_forward(
                x, 
                self.weight, 
                torch.tensor([], dtype=x.dtype, device=x.device)
            )

